create type public.inventory_kind as enum('grano','semilla','fertilizante','fitosanitario','veterinario','combustible','otro');
create type public.inventory_movement_type as enum('ingreso','egreso','reserva','liberacion','ajuste');
create table public.inventory_items(id uuid primary key default gen_random_uuid(),farm_id uuid not null references public.farms(id)on delete cascade,name text not null,kind public.inventory_kind not null,unit text not null,location text not null,origin_campaign text,opening_quantity numeric(16,3)not null default 0,minimum_quantity numeric(16,3)not null default 0,unit_value_ars numeric(16,2)not null default 0,physical_count numeric(16,3),counted_at date,active boolean not null default true,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(farm_id,name,location));
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),item_id uuid not null references public.inventory_items(id)on delete cascade,movement_date date not null,movement_type public.inventory_movement_type not null,quantity numeric(16,3)not null check(quantity<>0),concept text not null,reference text,work_order_id uuid references public.field_operations(id)on delete set null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),check((movement_type in('ingreso','egreso','reserva','liberacion')and quantity>0)or movement_type='ajuste'));
alter table public.inventory_items enable row level security;alter table public.inventory_movements enable row level security;create policy inventory_items_access on public.inventory_items for all to authenticated using(public.can_access_farm(farm_id))with check(public.can_manage_farm(farm_id));create policy inventory_movements_access on public.inventory_movements for all to authenticated using(exists(select 1 from public.inventory_items i where i.id=item_id and public.can_access_farm(i.farm_id)))with check(exists(select 1 from public.inventory_items i where i.id=item_id and public.can_manage_farm(i.farm_id)));
create view public.inventory_position with(security_invoker=true)as select i.id,i.farm_id,f.name farm_name,i.name,i.kind,i.unit,i.location,i.origin_campaign,i.opening_quantity,i.minimum_quantity,i.unit_value_ars,i.physical_count,i.counted_at,(i.opening_quantity+coalesce(sum(case when m.movement_type='ingreso'then m.quantity when m.movement_type='egreso'then-m.quantity when m.movement_type='ajuste'then m.quantity else 0 end),0))::numeric(16,3)theoretical_quantity,coalesce(sum(case when m.movement_type='reserva'then m.quantity when m.movement_type='liberacion'then-m.quantity else 0 end),0)::numeric(16,3)reserved_quantity,(i.opening_quantity+coalesce(sum(case when m.movement_type='ingreso'then m.quantity when m.movement_type='egreso'then-m.quantity when m.movement_type='ajuste'then m.quantity when m.movement_type='reserva'then-m.quantity when m.movement_type='liberacion'then m.quantity else 0 end),0))::numeric(16,3)available_quantity,case when i.physical_count is null then null else i.physical_count-(i.opening_quantity+coalesce(sum(case when m.movement_type='ingreso'then m.quantity when m.movement_type='egreso'then-m.quantity when m.movement_type='ajuste'then m.quantity else 0 end),0))end::numeric(16,3)count_difference from public.inventory_items i join public.farms f on f.id=i.farm_id left join public.inventory_movements m on m.item_id=i.id where i.active group by i.id,i.farm_id,f.name,i.name,i.kind,i.unit,i.location,i.origin_campaign,i.opening_quantity,i.minimum_quantity,i.unit_value_ars,i.physical_count,i.counted_at;grant select on public.inventory_position to authenticated;
create or replace function public.record_inventory_movement(p_item_id uuid,p_date date,p_type public.inventory_movement_type,p_quantity numeric,p_concept text,p_reference text default null,p_work_order_id uuid default null)returns uuid language plpgsql security definer set search_path=''as $$declare v_item public.inventory_items;v_current numeric;v_id uuid;begin select * into v_item from public.inventory_items where id=p_item_id for update;if v_item.id is null or not public.can_manage_farm(v_item.farm_id)then raise exception 'Ítem inexistente o sin permiso'using errcode='42501';end if;select theoretical_quantity into v_current from public.inventory_position where id=p_item_id;if p_type='egreso'and p_quantity>v_current then raise exception 'El egreso supera el stock teórico';end if;insert into public.inventory_movements(item_id,movement_date,movement_type,quantity,concept,reference,work_order_id,created_by)values(p_item_id,p_date,p_type,p_quantity,trim(p_concept),nullif(trim(p_reference),''),p_work_order_id,auth.uid())returning id into v_id;return v_id;end;$$;grant execute on function public.record_inventory_movement(uuid,date,public.inventory_movement_type,numeric,text,text,uuid)to authenticated;
